#include <stdio.h>

int is_power_of_two(unsigned int n) {
    return n > 0 && (n & (n - 1)) == 0;
}

int main() {
    unsigned int tests[] = {1, 6, 16, 18, 64, 100};
    for (int i = 0; i < 6; i++) {
        printf("%u: %s\n", tests[i], is_power_of_two(tests[i]) ? "yes" : "no");
    }
    return 0;
}
